 async function checkBattle(cross){if(busy||!selectedRun)return;const a=baseRuns.find(r=>r.seed===selectedRun.seed)||selectedRun,b=candidateRuns.find(r=>r.seed===selectedRun.seed)||a,sa=a.battles.find(x=>x.stage===selectedStage),sb=b.battles.find(x=>x.stage===selectedStage);if(!sa||!sb){notice('一个方案尚未到这关，不能编造等级来比较。',true);return;}lock(true);notice('正在逐场检验，原始样本与失败结果会一起保留。');try{const result=await callWorker({type:'battleCheck',args:[a.inputGame,b.inputGame,selectedStage,sa.levels,sb.levels,selectedRun.seed,Number(by('cgTrials').value),cross]});battleChecks.push(result);by('cgCheckResults').innerHTML='<p>第'+selectedStage+'关；配对编号起点'+result.seed+'；胜场时间只统计胜场，不能把死亡更快当作更快过关。</p><div class="scroll"><table><thead><tr><th>敌人</th><th>方案</th><th>胜 / 死亡 / 超时 / 同归于尽</th><th>胜率与95%模拟区间</th><th>胜场平均 / 最慢10%时间</th></tr></thead><tbody>'+result.rows.flatMap(r=>['before','after'].map((side,i)=>{const s=r[side];return '<tr><td>'+r.name+'</td><td>'+(i?'修改后':'修改前')+'</td><td>'+[s.wins,s.deaths,s.timeouts,s.draws].join(' / ')+'</td><td>'+f(s.winRate*100)+'%（'+f(s.winLow*100)+'%至'+f(s.winHigh*100)+'%）</td><td>'+f(s.meanWinTime)+' / '+f(s.p90WinTime)+'秒</td></tr>';})).join('')+'</tbody></table></div>';notice('检验完成；配置没有被敌人模板覆盖，原始样本随完整结果导出。');}catch(error){notice(error.message,true);}finally{lock(false);}}
