 function scaffold(g){const s=copy(CONNECTED_EXAMPLE);for(const k of ['name','rules','economy','behavior','goals','goalUnits','simulation'])if(g[k]!==undefined)s[k]=copy(g[k]);for(const k of ['rewardBase','rewardStep'])s.world[k]=g.world[k]??'0';return s;}
